def kernel(self, A: list):
        for t in range(0, self.TSTEPS - 1 + 1):
            for i in range(1, self.N - 2 + 1):
                for j in range(1, self.N - 2 + 1):
                    A[i][j] = (A[i - 1][j - 1] + A[i - 1][j] + A[i - 1][j + 1]
                               + A[i][j - 1] + A[i][j] + A[i][j + 1]
                               + A[i + 1][j - 1] + A[i + 1][j] + A[i + 1][j + 1]) / 9.0
